export type GemMonsterId = (typeof GEM_MONSTER_CATALOG)[number]["id"];

const MODELS_ON_DISK = GEM_MONSTER_CATALOG.filter((m) => SHIPPED_MONSTER_IDS.has(m.id));

/** True when only one pet GLB is deployed — every house gets that model. */
export const GEM_MONSTERS_DRAGON_ONLY = MODELS_ON_DISK.length <= 1;

export const GEM_MONSTER_MODELS = (
  MODELS_ON_DISK.length > 0 ? MODELS_ON_DISK : [GEM_MONSTER_CATALOG[0]!]
) as readonly (typeof GEM_MONSTER_CATALOG)[number][];

const DEFAULT_MONSTER = GEM_MONSTER_CATALOG[0]!;

function hashHouseId(id: string) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i += 1) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function gemMonsterForHouse(house: Pick<PublicHouse, "id" | "theme" | "kind">): GemMonsterId {
  if (GEM_MONSTERS_DRAGON_ONLY) {
    return GEM_MONSTER_MODELS[0]!.id;
  }
  void house.theme;
  void house.kind;
  const pool = GEM_MONSTER_MODELS;
  const idx = hashHouseId(house.id) % pool.length;
  return pool[idx]!.id;
}

export function gemMonsterMeta(monsterId: GemMonsterId) {
  return GEM_MONSTER_CATALOG.find((m) => m.id === monsterId) ?? DEFAULT_MONSTER;
}

/** Slight per-house hue so repeats feel a bit different on the bag map. */
export function gemMonsterTint(houseId: string) {
  const hue = (hashHouseId(houseId) % 360) / 360;
  return { hue, saturation: 0.35, lightness: 0.08 };
}

/** Cute display name (e.g. «עכי העכביש»). */
export function gemLabelHe(variantOrMonsterId: string) {
  const meta = GEM_MONSTER_CATALOG.find((m) => m.id === variantOrMonsterId);
  return meta?.petNameHe ?? meta?.labelHe ?? DEFAULT_MONSTER.petNameHe;
}

/** Short species label when needed. */
export function gemSpeciesLabelHe(variantOrMonsterId: string) {
  const meta = GEM_MONSTER_CATALOG.find((m) => m.id === variantOrMonsterId);
  return meta?.labelHe ?? DEFAULT_MONSTER.labelHe;
}

export function countGemEligibleHouses(houses: PublicHouse[]) {
  return houses.length;
}

export type GemFamily = "monster";

export function gemFamilyForHouse(house: Pick<PublicHouse, "id" | "theme" | "kind">): GemFamily {
  void house;
  return "monster";
}

/** @deprecated Use gemMonsterForHouse */
export function gemVariantForHouse(house: Pick<PublicHouse, "id" | "theme" | "kind">) {
  return gemMonsterForHouse(house);
}

export function gemVariantMeta(id: string) {
  const meta = gemMonsterMeta(id as GemMonsterId);
  return { id: meta.id, family: "monster" as const, labelHe: meta.petNameHe };
}
